(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.QuizCore=api;})(typeof window!=='undefined'?window:globalThis,function(){
'use strict';
const LETTERS=['A','B','C','D'],DAY=86400000;
const TYPES={single:'单选题',multi:'多选题',fill:'填空题',essay:'简答题'};
const RESULTS=['correct','wrong','remembered','again','ungraded'];
const cleanText=(v,max=12000)=>typeof v==='string'?v.slice(0,max):'';
function canonical(v){return [...new Set(Array.isArray(v)?v:[])].filter(x=>LETTERS.includes(x)).sort();}
function grade(selected,answer,type){if(!['single','multi'].includes(type))return null;const p=canonical(selected),k=canonical(answer);if(!k.length||(type==='single'&&k.length!==1))return null;return p.length===k.length&&p.every((l,i)=>l===k[i]);}
function normalizeFree(v){return String(v??'').replace(/[²³]/g,c=>c==='²'?'^2':'^3').normalize('NFKC').replace(/[−–]/g,'-').replace(/\\pi|π/g,'pi').replace(/√/g,'sqrt').replace(/sqrt\((\d+)\)/g,'sqrt$1').replace(/\s+/g,'').replace(/；/g,';').replace(/^\$(.*)\$$/,'$1');}
function sameWriting(input,accepted){const s=normalizeFree(input);return !!s&&Array.isArray(accepted)&&accepted.some(a=>normalizeFree(a)===s);}
function blankState(){return {version:1,records:{},history:[],overrides:{},settings:{goal:20,autoSubmit:false,dailyType:''},active:null};}
function dateKey(at){const d=new Date(at);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function advance(record,result,now){const r={...record};r.attempts=(r.attempts||0)+1;r.lastAt=now;r.lastResult=result;if(['correct','remembered'].includes(result)){r.streak=(r.streak||0)+1;r.stage=Math.min(4,(r.stage||0)+1);r.due=now+[1,3,7,14][r.stage-1]*DAY;if(result==='correct')r.correct=(r.correct||0)+1;if(r.streak>=2)r.inWrong=false;}else if(['wrong','again'].includes(result)){r.streak=0;r.stage=0;r.due=now;r.inWrong=true;if(result==='wrong')r.wrong=(r.wrong||0)+1;}else{r.due=now+DAY;}return r;}
function shuffle(list,rng=Math.random){const a=list.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function matches(q,f={}){if(f.type&&q.type!==f.type)return false;if(f.year&&q.year!==Number(f.year))return false;if(f.region&&q.region!==f.region)return false;if(f.source&&q.sourceId!==Number(f.source))return false;if(f.search){const hay=`${q.year} ${q.source} ${q.number} 第${q.number}题 ${TYPES[q.type]} ${q.elective?'选考题':''}`;if(!f.search.trim().split(/\s+/).every(t=>hay.toLowerCase().includes(t.toLowerCase())))return false;}return true;}
function summary(s,qs,now=Date.now()){const r=s.records,graded=s.history.filter(h=>['correct','wrong'].includes(h.result)),correct=graded.filter(h=>h.result==='correct').length;return {practiced:qs.filter(q=>r[q.id]?.attempts>0).length,mastered:qs.filter(q=>r[q.id]?.streak>=2).length,wrong:qs.filter(q=>r[q.id]?.inWrong).length,favorites:qs.filter(q=>r[q.id]?.favorite).length,due:qs.filter(q=>r[q.id]?.due&&r[q.id].due<=now).length,today:s.history.filter(h=>dateKey(h.at)===dateKey(now)).length,graded:graded.length,correct,accuracy:graded.length?Math.round(correct/graded.length*100):null,selfReviewed:s.history.filter(h=>['remembered','again'].includes(h.result)).length};}
function importState(raw,validIds){if(!raw||raw.version!==1||!raw.records||typeof raw.records!=='object'||Array.isArray(raw.records))throw new Error('备份格式不正确');const s=blankState(),valid=new Set(validIds);for(const[id,r]of Object.entries(raw.records)){if(!valid.has(id)||!r||typeof r!=='object')continue;const c={};for(const k of ['attempts','correct','wrong','streak','stage','due','lastAt'])if(Number.isFinite(r[k])&&r[k]>=0)c[k]=Math.min(r[k],1e14);c.stage=Math.min(4,c.stage||0);for(const k of ['favorite','inWrong','flagged'])c[k]=r[k]===true;c.notes=cleanText(r.notes);c.draft=cleanText(r.draft);c.lastSelection=canonical(r.lastSelection);c.lastResult=RESULTS.includes(r.lastResult)?r.lastResult:'ungraded';s.records[id]=c;}
s.history=(Array.isArray(raw.history)?raw.history:[]).filter(h=>valid.has(h.id)&&Number.isFinite(h.at)&&RESULTS.includes(h.result)).slice(-5000).map(h=>({id:h.id,at:h.at,result:h.result,selected:canonical(h.selected),answer:canonical(h.answer),text:cleanText(h.text,2000),answerText:cleanText(h.answerText,2000),overridden:h.overridden===true,seconds:Math.max(0,Math.min(86400,Number(h.seconds)||0))}));
for(const[id,v]of Object.entries(raw.overrides||{})){if(!valid.has(id)||!v)continue;const a=canonical(v.answer),t=cleanText(v.answerText,4000);if(a.length||t)s.overrides[id]={answer:a,answerText:t,at:Number(v.at)||Date.now()};}
if([5,10,20,30,50].includes(raw.settings?.goal))s.settings.goal=raw.settings.goal;s.settings.autoSubmit=raw.settings?.autoSubmit===true;if(Object.hasOwn(TYPES,raw.settings?.dailyType))s.settings.dailyType=raw.settings.dailyType;return s;}
function restoreSession(raw,validIds){if(!raw||!Array.isArray(raw.ids)||!raw.ids.length||!['quiz','flash'].includes(raw.mode))return null;const valid=new Set(validIds),ids=[...new Set(raw.ids)];if(!ids.every(id=>valid.has(id)))return null;const a={ids,mode:raw.mode,label:cleanText(raw.label,40),index:Math.min(ids.length-1,Math.max(0,Math.floor(Number(raw.index)||0))),startedAt:Number(raw.startedAt)||Date.now(),questionStartedAt:Number(raw.questionStartedAt)||Date.now(),results:{},picks:{},revealed:{},drafts:{}};for(const id of ids){a.picks[id]=canonical(raw.picks?.[id]);a.drafts[id]=cleanText(raw.drafts?.[id]);a.revealed[id]=raw.revealed?.[id]===true;const r=raw.results?.[id];if(r&&RESULTS.includes(r.result))a.results[id]={result:r.result,selected:canonical(r.selected),answer:canonical(r.answer),text:cleanText(r.text),answerText:cleanText(r.answerText,4000),at:Number(r.at)||Date.now(),seconds:Math.max(0,Number(r.seconds)||0),overridden:r.overridden===true};}return a;}
return {LETTERS,DAY,TYPES,canonical,grade,normalizeFree,sameWriting,blankState,dateKey,advance,shuffle,matches,summary,importState,restoreSession};
});
